def calculate_expected_time(N, M):
    p = 1 / 2
    expected_time_per_case = 0
    for i in range(1, N + 10):  # Assuming it will take at most 10 attempts to succeed
        probability = (p ** i) * ((1 - p) ** (i - 1))
        if i == 1:
            expected_time_per_case += probability * 1900
        else:
            expected_time_per_case += probability * (1900 * i)
    return int(expected_time_per_case * M + 100 * (N - M))

