from sys import stdin, stdout

class DisjointSetUnion:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        px, py = self.find(x), self.find(y)
        if px == py:
            return False
        if self.rank[px] > self.rank[py]:
            self.parent[py] = px
        elif self.rank[px] < self.rank[py]:
            self.parent[px] = py
        else:
            self.parent[px] = py
            self.rank[py] += 1
        return True

def main():
    n, m, D = map(int, stdin.readline().split())
    edges = []
    for _ in range(m):
        u, v = map(int, stdin.readline().split())
        if (u == 1 and v > D) or (v == 1 and u > D):
            continue
        edges.append((u - 1, v - 1))
    dsu = DisjointSetUnion(n)
    tree_edges = []
    for u, v in edges:
        if dsu.union(u, v):
            tree_edges.append((u + 1, v + 1))
    if len(tree_edges) < n - 1 or sum(1 for u, v in tree_edges if u == 1 or v == 1) != D:
        print("NO")
    else:
        print("YES")
