import sys
from collections import defaultdict, deque

def find_spanning_tree(n, m, D, edges):
    adj_list = defaultdict(list)
    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)

    if len(adj_list[1]) < D:
        return None

    visited = [False] * (n + 1)
    queue = deque([1])
    visited[1] = True
    tree_edges = []
    count = 0

    while queue and count < n - 1:
        u = queue.popleft()
        for v in adj_list[u]:
            if not visited[v]:
                visited[v] = True
                tree_edges.append((u, v))
                queue.append(v)
                count += 1
                break

    if count < n - 1:
        return None

    degree_count = sum(1 for u, _ in tree_edges if u == 1) + sum(1 for _, v in tree_edges if v == 1)

    while degree_count > D:
        i = next((i for i, (u, v) in enumerate(tree_edges) if u != 1 and v != 1), None)
        if i is not None:
            tree_edges.pop(i)
            degree_count -= 1
        else:
            return None

    while degree_count < D:
        for u, v in edges:
            if (u, v) not in tree_edges and (v, u) not in tree_edges and (u != 1 or v != 1):
                if u == 1 or v == 1:
                    if any(not visited[w] for w in adj_list[v]) or any(not visited[w] for w in adj_list[u]):
                        tree_edges.append((u, v))
                        degree_count += 1
                        break

    return tree_edges


def main():
    n, m, D = map(int, input().split())
    edges = []
    for _ in range(m):
        u, v = map(int, input().split())
        edges.append((u, v))

    spanning_tree = find_spanning_tree(n, m, D, edges)

    if spanning_tree is None:
        print("NO")
    else:
        print("YES")
        for u, v in spanning_tree:
            print(f"{min(u, v)} {max(u, v)}")


if __name__ == "__main__":
    main()
