def find_spanning_tree(n, m, D, edges):
    parent = list(range(n + 1))
    rank = [0] * (n + 1)
    used_edges = []

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        root_x = find(x)
        root_y = find(y)
        if root_x != root_y:
            if rank[root_x] > rank[root_y]:
                parent[root_y] = root_x
            else:
                parent[root_x] = root_y
                if rank[root_x] == rank[root_y]:
                    rank[root_y] += 1

    edges_with_node_1 = []
    other_edges = []

    for edge in edges:
        if 1 in edge:
            edges_with_node_1.append(edge)
        else:
            other_edges.append(edge)

    used_edges_from_node_1 = edges_with_node_1[:D]
    used_edges.extend(used_edges_from_node_1)

    for edge in used_edges_from_node_1:
        union(edge[0], edge[1])

    for edge in other_edges:
        if find(edge[0]) != find(edge[1]):
            used_edges.append(edge)
            union(edge[0], edge[1])

    return used_edges

def main():
    n, m, D = map(int, input().split())
    edges = []
    for _ in range(m):
        u, v = map(int, input().split())
        edges.append([u, v])

