    degree_count = [0] * (n + 1)
    for u, v in edges:
        if find(u) != find(v):
            union(u, v)
            spanning_tree_edges.append((u, v))
            degree_count[u] += 1
            degree_count[v] += 1

    if len(spanning_tree_edges) < n - 1 or degree_count[1] > D:
        return "NO"

    excess_edges = []
    for u, v in edges:
        if (u, v) not in spanning_tree_edges and (v, u) not in spanning_tree_edges:
            excess_edges.append((u, v))

    required_edges_to_remove = degree_count[1] - D
    removable_edges = [(u, v) for u, v in spanning_tree_edges if 1 in (u, v)]
