import sys

def min_songs_to_compress(n, m, songs):
    savings = sorted([(a - b, i) for i, (a, b) in enumerate(songs)], reverse=True)
    compressed = [False] * n
    count = 0
    total_size = sum(a for a, _ in songs)

    if total_size <= m:
        return 0

    for saving, _ in savings:
        if total_size > m:
            total_size -= saving
            count += 1
        else:
            break

    if total_size > m:
        return -1
    else:
        return count

def main():
