from collections import defaultdict, deque

def main():
    n, k = map(int, input().split())
    p = list(map(lambda x: int(x) - 1, input().split()))
    q = list(map(lambda x: int(x) - 1, input().split()))

    graph = defaultdict(list)
    for i in range(n):
        if i < n - 1:
            graph[p[i]].append(p[i + 1])
            graph[q[i]].append(q[i + 1])

    indegree = {i: 0 for i in range(n)}
    for node in graph:
        for neighbor in graph[node]:
            indegree[neighbor] += 1

    queue = deque([node for node in indegree if indegree[node] == 0])
    topological_order = []
    while queue:
        node = queue.popleft()
        topological_order.append(node)
        for neighbor in graph[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                queue.append(neighbor)

    if len(topological_order) != n:
        print("NO")
        return

    ans = [""] * n
    cnt = 0
    for node in topological_order:
        while graph[node]:
            next_node = graph[node].pop()
            ans[next_node] = chr(ord('a') + cnt)
            if not graph[node]:
                break
        if not graph[node]:
            ans[node] = chr(ord('a') + cnt)
            cnt += 1

    unique_chars = set(ans)
    while len(unique_chars) < k:
        for i in range(n):
            if ans[i] == 'z':
                continue
            ans[i] = chr(ord(ans[i]) + 1)
            unique_chars.add(ans[i])
            break
        else:
            print("NO")
            return

