        graph[u].append(v)
        rev_graph[v].append(u)

    protectable = [set() for _ in range(n)]
    visited = [False] * n
    for i in range(n):
        if not visited[i]:
            dfs(graph, visited, i)
            queue = deque([i])
            while queue:
                node = queue.popleft()
                protectable[i].add(node)
                for neighbor in graph[node]:
                    if not visited[neighbor]:
                        queue.append(neighbor)
                        visited[neighbor] = True

    for i in range(n):
        if not visited[i]:
            dfs(rev_graph, visited, i)
            queue = deque([i])
            while queue:
                node = queue.popleft()
                protectable[i].add(node)
                for neighbor in rev_graph[node]:
                    if not visited[neighbor]:
                        queue.append(neighbor)
                        visited[neighbor] = True

