def is_valid_day(events):
    employees_in = set()
    for event in events:
        if event > 0:
            if event in employees_in:
                return False
            employees_in.add(event)
        else:
            if -event not in employees_in:
                return False
            employees_in.remove(-event)
    return len(employees_in) == 0

def partition_events(n, events):
    days = []
    current_day = []
    for event in events:
        current_day.append(event)
        if is_valid_day(current_day):
            continue
        else:
            if not current_day[:-1]:
                return [-1]
            days.append(len(current_day) - 1)
            current_day = [event]
    if len(current_day) > 0 and not is_valid_day(current_day):
        return [-1]
    days.append(len(current_day))
    return [len(days)] + days

