import sys

def calculate_max_strength(a):
    max_sum = [0] * len(a)
    min_sum = [0] * len(a)

    for i in range(len(a)):
        if i == 0:
            max_sum[i] = a[i]
            min_sum[i] = -a[i]
        else:
            max_sum[i] = max(max_sum[i-1], a[i])
            min_sum[i] = min(min_sum[i-1], -a[i])

    for i in range(1, len(a)):
        max_sum[i] = max(max_sum[i], max_sum[i-1] + a[i])
        min_sum[i] = min(min_sum[i], min_sum[i-1] - a[i])

    return max(max_sum[-1], -min_sum[-1])

