import sys

def min_changes(grid):
    n, m = len(grid), len(grid[0])
    directions = [[0] * m for _ in range(n)]

    # Initialize last row and column with 0s (no changes needed)
    for i in range(m - 1, -1, -1):
        if grid[n-1][i] == 'R':
            directions[n-1][i] = 0
        else:
            directions[n-1][i] = 1

    for i in range(n - 2, -1, -1):
        for j in range(m - 1, -1, -1):
            if grid[i][j] == 'R':
                # If the cell below has a direction D (going down), change it
                if j < m - 1 and directions[i+1][j] > 0:
                    directions[i][j] = directions[i+1][j]
                else:
                    directions[i][j] = float('inf')
            else: # grid[i][j] == 'D'
                # If the cell to the right has a direction R (going right), change it
                if i < n - 1 and j + 1 < m and directions[i][j+1] > 0:
                    directions[i][j] = directions[i][j+1]
                else:
                    directions[i][j] = float('inf')

    min_change_count = float('inf')
    for row in range(n):
        if grid[row][m-2] == 'R':
            min_change_count = min(min_change_count, sum(directions[row]))
        elif row < n - 1 and grid[row+1][m-2] == 'D':
            min_change_count = min(min_change_count, 1 + sum([directions[i][j] for i in range(row) for j in range(m)]))

    return min_change_count


