def min_changes_to_make_conveyor_belt_functional(n, m, grid):
    directions = {'R': (0, 1), 'D': (1, 0)}
    changes = [[float('inf')] * m for _ in range(n)]

    queue = deque([(n-1, m-1)])
    changes[n-1][m-1] = 0

    while queue:
        x, y = queue.popleft()
        if x > 0 and (y == m - 1 or grid[x-1][y] == 'D'):
            if changes[x-1][y] > changes[x][y]:
                changes[x-1][y] = changes[x][y]
                queue.append((x-1, y))
        if y > 0 and (x == n - 1 or grid[x][y-1] == 'R'):
            if changes[x][y-1] > changes[x][y]:
                changes[x][y-1] = changes[x][y]
                queue.append((x, y-1))

    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'D' and j < m - 1:
                if changes[i][j+1] + 1 < changes[i][j]:
                    changes[i][j] = changes[i][j+1] + 1
                    queue.append((i, j))
            elif grid[i][j] == 'R' and i < n - 1:
                if changes[i+1][j] + 1 < changes[i][j]:
                    changes[i][j] = changes[i+1][j] + 1
                    queue.append((i, j))

    while queue:
