from collections import deque

def min_changes(grid):
    n, m = len(grid), len(grid[0])
    directions = {'R': (0, 1), 'D': (1, 0)}
    visited = [[False]*m for _ in range(n)]

    def bfs(i, j):
        queue = deque([(i, j)])
        visited[i][j] = True
        changes = 0

        while queue:
            x, y = queue.popleft()
            if grid[x][y] == 'C':
                return changes

            dx, dy = directions[grid[x][y]]
            nx, ny = x + dx, y + dy

            if nx < n and ny < m and not visited[nx][ny]:
                queue.append((nx, ny))
                visited[nx][ny] = True
            elif (dx == 0 or ny >= m) and (dy == 0 or nx >= n):
                changes += 1
                if dy == 0:
                    grid[x][y] = 'D'
                else:
                    grid[x][y] = 'R'
                dx, dy = directions[grid[x][y]]
                nx, ny = x + dx, y + dy
                queue.append((nx, ny))
                visited[nx][ny] = True

    min_changes = float('inf')
    for i in range(n):
        for j in range(m):
            if not visited[i][j]:
                changes = bfs(i, j)
                min_changes = min(min_changes, changes)

    return min_changes


def main():
