import sys

def min_changes(grid):
    n = len(grid)
    m = len(grid[0])

    changes = 0

    for i in range(n - 1, -1, -1):
        for j in range(m - 1, -1, -1):
            if (i, j) == (n - 1, m - 1):
                continue
            down_reachable = False
            right_reachable = False

            if i < n - 1:
                down_reachable = is_reachable(grid, i + 1, j)

            if j < m - 1:
                right_reachable = is_reachable(grid, i, j + 1)

            if not (down_reachable or right_reachable):
                return float('inf')

            if grid[i][j] == 'R' and down_reachable:
                changes += 1
            elif grid[i][j] == 'D' and right_reachable:
                changes += 1

    return changes

def is_reachable(grid, i, j):
    n = len(grid)
    m = len(grid[0])

    if (i, j) == (n - 1, m - 1):
        return True

    reachable = False

    if grid[i][j] == 'R' and j < m - 1:
        reachable |= is_reachable(grid, i, j + 1)

    if grid[i][j] == 'D' and i < n - 1:
        reachable |= is_reachable(grid, i + 1, j)

    return reachable

def solve():
