        for new_dir_x, new_dir_y in directions:
            if (new_dir_x, new_dir_y) == (-dir_x, -dir_y):
                continue
            new_turns = turns + ((new_dir_x, new_dir_y) != (dir_x, dir_y))
            if new_turns > 2:
                continue
            count += dfs(x + new_dir_x, y + new_dir_y, new_dir_x, new_dir_y, new_turns, visited.copy())
        return count

    count = 0
    for x in range(n):
        for y in range(m):
            if is_valid(x, y) and (x == 0 or x == n - 1 or y == 0 or y == m - 1):
                if (x > 0 and x < n - 1) or (y > 0 and y < m - 1):
                    for dir_x, dir_y in directions:
                        new_x, new_y = x + dir_x, y + dir_y
                        count += dfs(new_x, new_y, dir_x, dir_y, 0, {(x, y)})
    return count // 2

