            return 0

        count = 0
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny) and (nx, ny) not in visited:
                visited.add((x, y))
                if turns < 2 or (dx, dy) == direction:
                    count += dfs(nx, ny, (dx, dy), turns + (dx != direction[0] or dy != direction[1]))
                visited.remove((x, y))

