def solve(n, m, grid):
    def is_valid_pipe(pipe):
        if len(pipe) < 2:
            return False
        start = pipe[0]
        end = pipe[-1]
        if start[0] == 0 or start[0] == n - 1:
            if start[1] == 0 or start[1] == m - 1:
                return False
        else:
            return False
        if end[0] == 0 or end[0] == n - 1:
            if end[1] == 0 or end[1] == m - 1:
                return False
        else:
            return False
        turns = 0
        for i in range(1, len(pipe)):
            dx = pipe[i][0] - pipe[i - 1][0]
            dy = pipe[i][1] - pipe[i - 1][1]
            if dx != 0 and dy != 0:
                return False
            if dx == 0 and dy == 0:
                return False
            if i > 1:
                pdx = pipe[i - 1][0] - pipe[i - 2][0]
                pdy = pipe[i - 1][1] - pipe[i - 2][1]
                if dx != pdx and dy != pdy:
                    turns += 1
        return turns <= 2

    def dfs(i, j, prev_dir):
        if i < 0 or i >= n or j < 0 or j >= m or grid[i][j] == '#':
            return []
        res = []
        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            if prev_dir and abs(di) + abs(dj) != abs(prev_dir[0]) + abs(prev_dir[1]):
                continue
            pipe = [(i, j)]
            stack = [(i + di, j + dj, (di, dj))]
            while stack:
                x, y, dir = stack.pop()
                if x < 0 or x >= n or y < 0 or y >= m or grid[x][y] == '#':
                    continue
                pipe.append((x, y))
                for ddi, ddj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    if abs(ddi) + abs(ddj) != abs(dir[0]) + abs(dir[1]):
                        continue
                    stack.append((x + ddi, y + ddj, (ddi, ddj)))
            if is_valid_pipe(pipe):
                res.append(pipe)
        return res

    pipes = []
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                pipes.extend(dfs(i, j, None))
    return len(pipes)

