def get_paths(grid, start):
    paths = []
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    stack = [(start, [start])]
    while stack:
        (x, y), path = stack.pop()
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and grid[nx][ny] == '.':
                new_path = path + [(nx, ny)]
                if (nx, ny) in [(i, j) for i in range(len(grid)) for j in range(len(grid[0])) if i in (0, len(grid) - 1) or j in (0, len(grid[0]) - 1)]:
                    if is_valid_path(grid, new_path):
                        paths.append(new_path)
                else:
                    stack.append(((nx, ny), new_path))
    return paths


