def calculate_pipes(n, m, grid):
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    visited = set()

    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < m and grid[x][y] == '.'

    def dfs(x, y, dx, dy, turns):
        if not is_valid(x, y) or (x, y) in visited:
            return
        if turns > 2:
            return

        visited.add((x, y))

        for ndx, ndy in directions:
            nx, ny = x + ndx, y + ndy
            if is_valid(nx, ny):
                dfs(nx, ny, dx, dy, turns)
                if ndx != dx or ndy != dy:
                    dfs(nx, ny, ndx, ndy, turns + 1)

        visited.remove((x, y))

    def count_pipes(x, y):
        count = 0
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny):
                temp_grid = [row[:] for row in grid]
                queue = [(nx, ny)]
                temp_grid[nx][ny] = '*'
                while queue:
                    cx, cy = queue.pop(0)
                    for ndx, ndy in directions:
                        nnx, nny = cx + ndx, cy + ndy
                        if is_valid(nnx, nny) and (nnx, nny) not in visited:
                            queue.append((nnx, nny))
                            temp_grid[nnx][nny] = '*'
                count += 1 if all(temp_grid[i].count('*') == 2 for i in range(n)) else 0
        return count

    pipes = 0
    for x in range(1, n - 1):
        if is_valid(x, 0):
            pipes += count_pipes(x, 0)
    for y in range(1, m - 1):
        if is_valid(0, y):
            pipes += count_pipes(0, y)

    return pipes

