                if i < len(pipe) - 1 and abs(pipe[i+1][0] - pipe[i][0]) == 1:
                    turns += 1
            elif dx == 1 and dy == 0:
                if i < len(pipe) - 1 and abs(pipe[i+1][1] - pipe[i][1]) == 1:
