def count_ways(grid):
    n, m = len(grid), len(grid[0])
    ways = 0

    # Try all possible start positions on the border
    for i in range(n):
        for j in range(m):
            if (i == 0 or i == n - 1) and (j != 0 and j != m - 1):
                if grid[i][j] == '.':
                    ways += try_start(grid, i, j, 'down')
                    ways += try_start(grid, i, j, 'up')
            elif (i != 0 and i != n - 1) and (j == 0 or j == m - 1):
                if grid[i][j] == '.':
                    ways += try_start(grid, i, j, 'right')
                    ways += try_start(grid, i, j, 'left')

    return ways

def try_start(grid, i, j, direction):
    n, m = len(grid), len(grid[0])
    visited = [[False]*m for _ in range(n)]
    ways = 0
    stack = [(i, j, direction, 0, False)]

    while stack:
        x, y, d, turns, ended = stack.pop()
        if (x < 0 or x >= n or y < 0 or y >= m) or grid[x][y] == '#' or visited[x][y]:
            continue
        visited[x][y] = True

        # Check if we've reached the end of a pipe
        if (x == 0 or x == n - 1) and (d in ['up', 'down']):
            ended = True
        elif (y == 0 or y == m - 1) and (d in ['left', 'right']):
            ended = True

        # Add current position to the pipe if it's not a corner square
        if (x != 0 and x != n - 1) and (y != 0 and y != m - 1):
            pass
        elif (x == 0 or x == n - 1) and (y != 0 and y != m - 1):
            pass
        elif (i != 0 and i != n - 1) and (j == 0 or j == m - 1):
            pass

        # Check if we can extend the pipe in the current direction
        new_x, new_y = x + directions[d][0], y + directions[d][1]
        if (new_x < 0 or new_x >= n or new_y < 0 or new_y >= m) or grid[new_x][new_y] == '#' or visited[new_x][new_y]:
            pass
        else:
            stack.append((new_x, new_y, d, turns, ended))

        # Check if we can turn the pipe
        if turns < 2:
            for new_d in directions.keys():
                if (directions[d][0] == -directions[new_d][0] and directions[d][1] == -directions[new_d][1]):
                    continue
                new_x, new_y = x + directions[new_d][0], y + directions[new_d][1]
                if (new_x < 0 or new_x >= n or new_y < 0 or new_y >= m) or grid[new_x][new_y] == '#' or visited[new_x][new_y]:
                    continue
                stack.append((new_x, new_y, new_d, turns + 1, ended))

        # If we've reached the end of a pipe and it's valid, increment the count
        if ended:
            ways += 1

    return ways

