    def is_valid_pipe(x, y, dx, dy, turns):
        if not (0 <= x < n and 0 <= y < m) or grid[x][y] == '#':
            return False
        if turns > 2:
            return False
        if x in [0, n - 1] and y in [0, m - 1]:
            return False

        visited = set()
        while 0 <= x < n and 0 <= y < m:
            if (x, y) in visited:
                break
            visited.add((x, y))
            if grid[x][y] == '#':
                break
            x += dx
            y += dy

        return len(visited) > 1 and all(grid[u][v] != '#' for u, v in visited)

    count = 0
    directions = [(0, 1), (1, 0)]
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                for dx, dy in directions:
                    x, y = i + dx, j + dy
                    count += is_valid_pipe(x, y, -dx, -dy, 2)
                    while 0 <= x < n and 0 <= y < m and grid[x][y] == '.':
                        x += dx
                        y += dy
                    if 0 <= x < n and 0 <= y < m and grid[x][y] == '.':
                        count += is_valid_pipe(x, y, -dx, dy, 1)
                        count += is_valid_pipe(x, y, dx, -dy, 1)

    return count // 2

