def count_pipes(n, m, grid):
    def is_valid_pipe(pipe):
        turns = 0
        prev_dir = None
        for i in range(1, len(pipe)):
            x1, y1 = pipe[i-1]
            x2, y2 = pipe[i]
            dx, dy = x2 - x1, y2 - y1
            if abs(dx) + abs(dy) != 1:
                return False
            dir_ = (dx, dy)
            if prev_dir and dir_ != prev_dir:
                turns += 1
                if turns > 2:
                    return False
            prev_dir = dir_
        return True

    def dfs(x, y, visited, pipe):
        nonlocal count
        if len(pipe) > 0 and (x == 0 or x == n-1 or y == 0 or y == m-1):
            if is_valid_pipe(pipe):
                count += 1
            return
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] == '.' and (nx, ny) not in visited:
                dfs(nx, ny, visited | {(nx, ny)}, pipe + [(nx, ny)])

    count = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                dfs(i, j, {(i, j)}, [(i, j)])
    return count

