    def is_valid_pipe(pipe):
        pipe_set = set(pipe)
        for x, y in pipe:
            if grid[x][y] == '#':
                return False
            adjacent = [(x-1, y), (x+1, y), (x, y-1), (x, y+1)]
            count = 0
            for dx, dy in adjacent:
                if (dx, dy) in pipe_set:
                    count += 1
            if x == 0 or x == n - 1:
                if y == 0 or y == m - 1:
                    return False
                if count != 1:
                    return False
            elif y == 0 or y == m - 1:
                if count != 1:
                    return False
            else:
                if count != 2:
                    return False
        return True

    def dfs(x, y, pipe, turns):
        if len(pipe) > n + m - 2:
            return
        if x == 0 or x == n - 1:
            if y == 0 or y == m - 1:
                return
            if is_valid_pipe(pipe):
                yield pipe[:]
        else:
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] != '#':
                    new_turns = turns + int((dx, dy) != (pipe[-2][0] - pipe[-1][0], pipe[-2][1] - pipe[-1][1]))
                    if new_turns > 2:
                        continue
                    pipe.append((nx, ny))
                    yield from dfs(nx, ny, pipe, new_turns)
                    pipe.pop()

    pipes = set()
    for x in range(n):
        for y in range(m):
            if grid[x][y] == '.':
                if x == 0 or x == n - 1:
                    if y != 0 and y != m - 1:
                        pipe = [(x, y)]
                        yield from dfs(x, y, pipe, 0)
                elif y == 0 or y == m - 1:
                    if x != 0 and x != n - 1:
                        pipe = [(x, y)]
                        yield from dfs(x, y, pipe, 0)

    for pipe in pipes:
