            available_weights = [w for w in weights if w != (solution[-1] if solution else None)]
            if not available_weights:
                return None
            available_weights.sort()
            weight = max(available_weights)
            while left_sum + weight <= right_sum:
                try:
                    weight = next(w for w in reversed(weights) if w > weight and w != (solution[-1] if solution else None))
