def calculate_min_cost():
    n, a, r, m = map(int, input().split())
    heights = list(map(int, input().split()))

    min_costs = []
    for target_height in range(min(heights), max(heights) + 1):
        cost = 0
        excess_bricks = 0
        deficit_bricks = 0

        for height in heights:
            if height > target_height:
                excess_bricks += (height - target_height)
                cost += min(r, m) * (height - target_height)
            elif height < target_height:
                deficit_bricks += (target_height - height)

        if excess_bricks >= deficit_bricks:
            cost -= min(r, m) * deficit_bricks
            cost += a * deficit_bricks
        else:
            cost += a * (deficit_bricks - excess_bricks)

        min_costs.append(cost)

