from collections import defaultdict

def solve(n, users, messages):
    graph = defaultdict(list)
    for i in range(len(messages)):
        if messages[i][0] != '?':
            user = messages[i].split(':')[0]
            continue
        text = messages[i].split(':')[1]
        possible_users = []
        for u in users:
            if u not in text.split():
                possible_users.append(u)
        graph[i] = possible_users

    def dfs(index, path):
        if index == len(messages):
            return True
        if messages[index][0] != '?':
            user = messages[index].split(':')[0]
            if index > 0 and path[-1] == user:
                return False
            for mention in graph.get(index, []):
                if user not in text.split():
                    continue
                else:
                    return False
            path.append(user)
            return dfs(index + 1, path)
        else:
            for u in graph[index]:
                if index > 0 and path[-1] == u:
                    continue
                text = messages[index].split(':')[1]
                if u in text.split():
                    continue
                path.append(u)
                if dfs(index + 1, path):
                    return True
                path.pop()
            return False

    users_copy = users.copy()
    result = []
    if dfs(0, []):
        for i in range(len(messages)):
            if messages[i][0] != '?':
                user = messages[i].split(':')[0]
                text = messages[i].split(':')[1]
                result.append(f"{user}:{text}")
            else:
                for u in users_copy:
                    if u not in messages[i].split(':')[1].split():
                        user = u
                        break
                text = messages[i].split(':')[1]
                result.append(f"{user}:{text}")
        print('\n'.join(result))
    else:
        print('Impossible')

