import sys
import heapq

def min_penalty(n, colors):
    total = sum(colors)
    queue = [(-total, 0)]
    seen = set()

    while queue:
        neg_sum, moves = heapq.heappop(queue)

        if -neg_sum == n:
            return moves

        for k in [2, 3]:
            for split in combinations_with_replacement(range(1, len(colors) + 1), k):
                new_moves = moves + (-neg_sum)
                new_sum = 0
                new_colors = []

                start = 0
                for i in range(k):
                    end = start + split[i]
                    if end > len(colors):
                        break

                    group_sum = sum(colors[start:end])
                    new_sum += group_sum
                    new_colors.append(group_sum)

                    start = end

                if start < len(colors):
                    new_sum += sum(colors[start:])
                    new_colors.append(sum(colors[start:]))

                new_tuple = tuple(sorted(new_colors))
                if new_tuple not in seen:
                    seen.add(new_tuple)
                    heapq.heappush(queue, (-new_sum, new_moves))

def combinations_with_replacement(iterable, r):
    def combinations_with_replacement_recursive(iterable, r, current_combination=[]):
        if len(current_combination) == r:
            yield tuple(sorted(current_combination))
        else:
            for i in iterable:
                if not current_combination or i >= current_combination[-1]:
                    yield from combinations_with_replacement_recursive(iterable, r, current_combination + [i])

    return set(combinations_with_replacement_recursive(range(1, len(iterable) + 1), r))

