def min_charges(n, heights):
    max_height = max(heights)
    dp = [0] * (max_height + 1)

    for height in sorted(set(heights), reverse=True):
        if height > dp[height]:
            for i in range(height - 1, -1, -1):
                dp[i] = max(dp[i], dp[height] + 1)
        else:
