def is_polygon(mask, r, c):
    visited = [[False] * c for _ in range(r)]
    borders = 0
    holes = 0

    def dfs(i, j):
        nonlocal borders, holes
        if i < 0 or i >= r or j < 0 or j >= c:
            return
        if not mask[i][j]:
            if not visited[i][j]:
                borders += 1
                visited[i][j] = True
            return
        if visited[i][j]:
            holes += 1
            return
        visited[i][j] = True
        dfs(i - 1, j)
        dfs(i + 1, j)
        dfs(i, j - 1)
        dfs(i, j + 1)

    for i in range(r):
        for j in range(c):
            if not mask[i][j]:
                dfs(i, j)

