def get_polygons(R, C):
    polygons = set()
    for bits in range(1 << R * C):
        cells = [(i // C, i % C) for i in range(R * C) if (bits & (1 << i))]
        if not cells:
            continue
        min_row = min(cell[0] for cell in cells)
        min_col = min(cell[1] for cell in cells)
        max_row = max(cell[0] for cell in cells)
        max_col = max(cell[1] for cell in cells)

        is_polygon = True
        visited = set()
        stack = [cells[0]]
        while stack:
            row, col = stack.pop()
            if (row, col) not in visited:
                visited.add((row, col))
                neighbors = []
                if row > min_row and (row - 1, col) in cells:
                    neighbors.append((row - 1, col))
                if row < max_row and (row + 1, col) in cells:
                    neighbors.append((row + 1, col))
                if col > min_col and (row, col - 1) in cells:
                    neighbors.append((row, col - 1))
                if col < max_col and (row, col + 1) in cells:
                    neighbors.append((row, col + 1))

                if len(neighbors) == 0:
                    continue
                for neighbor in neighbors:
                    if neighbor not in visited:
                        stack.append(neighbor)

        is_polygon = len(cells) == len(visited)
        if is_polygon:
            polygons.add(tuple(sorted(((cell[0] - min_row, cell[1] - min_col) for cell in cells))))

    return len(polygons)


def main():
    R, C = map(int, input().split())
    total_polygons = 0
    for r_offset in range(R):
        for c_offset in range(C):
            polygons_in_box = get_polygons(R - r_offset, C - c_offset)
            total_polygons += polygons_in_box

