import sys

def count_polygons(R, C):
    grid = [[0] * C for _ in range(R)]
    directions = [(0, 1), (1, 0), (-1, 0), (0, -1)]

    def is_valid(x, y):
        return 0 <= x < R and 0 <= y < C

    def dfs(x, y, prev_x, prev_y, visited):
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if not is_valid(nx, ny) or (nx, ny) == (prev_x, prev_y) or (nx, ny) in visited:
                continue
            if grid[nx][ny] == 0 and len(visited) < R * C - 1:
                visited.add((nx, ny))
                dfs(nx, ny, x, y, visited)
                visited.remove((nx, ny))

    count = 0

    for mask in range(1 << (R * C)):
        grid = [[int(mask & (1 << (i * C + j))) > 0 for j in range(C)] for i in range(R)]
        if not any(grid[i][j] for i in range(R) for j in range(C)):
            continue

        holes = False
        visited = set()
        starts = [(i, j) for i in range(R) for j in range(C) if grid[i][j]]
        for start_x, start_y in starts:
            if (start_x, start_y) not in visited:
                visited.add((start_x, start_y))
                stack = [(start_x, start_y, -1, -1)]
                while stack:
                    x, y, prev_x, prev_y = stack.pop()
                    for dx, dy in directions:
                        nx, ny = x + dx, y + dy
                        if not is_valid(nx, ny) or grid[nx][ny] == 0 or (nx, ny) == (prev_x, prev_y):
                            continue
                        if (nx, ny) in visited and len(visited) > 1:
                            holes = True
                            break
                        elif (nx, ny) not in visited:
                            visited.add((nx, ny))
                            stack.append((nx, ny, x, y))
                    if holes:
                        break

        if not holes:
            count += 1

    return count


