        directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

        def dfs(row, col, prev_row, prev_col):
            if (row, col) in visited:
                return False
            visited.add((row, col))

            for dr, dc in directions:
                nr, nc = row + dr, col + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 1:
                    if (nr, nc) == (prev_row, prev_col):
                        continue
                    if not dfs(nr, nc, row, col):
                        return False

            return True

        for i in range(rows):
            for j in range(cols):
                if grid[i][j] == 1 and (i, j) not in visited:
                    if dfs(i, j, -1, -1):
                        return len(visited) > 2
                    else:
                        return False
        return True

    def is_connected(grid):
        visited = set()
        directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

        def dfs(row, col):
            if (row, col) in visited:
                return
            visited.add((row, col))

            for dr, dc in directions:
                nr, nc = row + dr, col + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 1:
                    dfs(nr, nc)

        found_one = False
        for i in range(rows):
            for j in range(cols):
                if grid[i][j] == 1:
                    dfs(i, j)
                    found_one = True
                    break
            if found_one:
                break

        for i in range(rows):
            for j in range(cols):
                if grid[i][j] == 1 and (i, j) not in visited:
                    return False

        return True

    def has_holes(grid):
        directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

        def dfs(row, col):
            if row < 0 or row >= rows or col < 0 or col >= cols:
                return True
            if grid[row][col] == 1:
                return False

            for dr, dc in directions:
                nr, nc = row + dr, col + dc
                if dfs(nr, nc):
                    return True

        return not dfs(0, 0)

    for p in itertools.product([0, 1], repeat=rows*cols):
        grid = [list(p[i:i+cols]) for i in range(0, len(p), cols)]
        if sum(sum(row) for row in grid) > 0 and is_connected(grid) and not has_holes(grid) and is_polygon(grid):
            count += 1

    return count

