import sys

def aho_corasick(strings):
    trie = defaultdict(list)
    for s in strings:
        node = 0
        for c in s:
            if (node, c) not in trie:
                trie[(node, c)] = len(trie)
            node = trie[(node, c)]

    queue = deque([0])
    failure = [None] * len(trie)
    while queue:
        node = queue.popleft()
        for c, child in [(c, v) for (n, c), v in trie.items() if n == node]:
            if child != 0 and failure[node] is not None:
                parent = failure[node]
                while parent is not None and (parent, c) not in trie:
                    parent = failure[parent]
                if parent is not None:
                    parent_child = trie[(parent, c)]
                    failure[child] = parent_child
            queue.append(child)

    return trie, failure

def find_longest_clue(strings):
    n = len(strings)
    trie, failure = aho_corasick(strings)
    queue = deque([(0, '')])
    visited = set([0])
    longest_clue = ''

    while queue:
        node, clue = queue.popleft()
        if len(clue) > len(longest_clue):
            longest_clue = clue
        for c in '01':
            child = trie.get((node, c))
            if child is None or child == 0:
                continue
            new_node = child
            if (new_node, 0) not in trie and (new_node, 1) not in trie:
                return longest_clue + c
            if new_node not in visited:
                queue.append((new_node, clue + c))
                visited.add(new_node)
    return -1

