    n = int(input())
    taboo_strings = []
    for _ in range(n):
        s = input()
        taboo_strings.append(s)
    return n, taboo_strings

def build_ac_automaton(taboo_strings):
    trie = {}
    fail = {}
    output = {}

    for string in taboo_strings:
        node = trie
        for char in string:
            if char not in node:
                node[char] = {}
            node = node[char]
        output[node] = True

    queue = deque([trie])
    while queue:
        node = queue.popleft()
        for char, child_node in node.items():
            if char == '0':
                next_node = trie
            elif char == '1':
                next_node = trie.get('1', {})
            else:
                continue

            fail[child_node] = None
            while next_node and char not in next_node:
                if output.get(next_node):
                    break
                next_node = fail.get(next_node, trie)

            if next_node and char in next_node:
                fail[child_node] = next_node[char]
                if output.get(fail[child_node]):
                    output[child_node] = True

            queue.append(child_node)

    return trie, fail, output

def find_longest_clue(trie, fail, output):
    max_length = 0
    clue = ''

    def dfs(node, string):
        nonlocal max_length, clue
        if len(string) > max_length:
            max_length = len(string)
            clue = string
        elif len(string) == max_length and string < clue:
            clue = string

        for char in '01':
            next_node = node.get(char, trie)
            while next_node and output.get(next_node):
                next_node = fail[next_node]
            if not next_node or next_node is trie:
                dfs(node, string + char)

    dfs(trie, '')
    return clue if max_length < 1000000 else -1

