                nx, ny = x + i, y + j
                if is_valid(nx, ny):
                    grid[nx] = grid[nx][:ny] + color + grid[nx][ny+1:]
        return True

    def undo_stamp(x, y):
        for i in range(3):
            for j in range(3):
                nx, ny = x + i, y + j
                if is_valid(nx, ny):
                    grid[nx] = grid[nx][:ny] + 'W' + grid[nx][ny+1:]

    def dfs(x, y):
