from collections import deque

def count_changes(grid, k):
    n = len(grid)
    m = len(grid[0])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    visited = [[False for _ in range(m)] for _ in range(n)]

    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < m

    def bfs(x, y, val):
        queue = deque([(x, y)])
        component = [(x, y)]
        visited[x][y] = True
        while queue:
            curr_x, curr_y = queue.popleft()
            for dx, dy in directions:
                new_x, new_y = curr_x + dx, curr_y + dy
                if is_valid(new_x, new_y) and not visited[new_x][new_y] and grid[new_x][new_y] == val:
                    queue.append((new_x, new_y))
                    component.append((new_x, new_y))
                    visited[new_x][new_y] = True
        return component

    def is_rectangular(component):
        min_x = min(x for x, y in component)
        max_x = max(x for x, y in component)
        min_y = min(y for x, y in component)
        max_y = max(y for x, y in component)
        expected_component = [(x, y) for x in range(min_x, max_x + 1) for y in range(min_y, max_y + 1)]
        return set(component) == set(expected_component)

    changes = 0
    for i in range(n):
        for j in range(m):
            if not visited[i][j]:
                component = bfs(i, j, grid[i][j])
                if not is_rectangular(component):
                    changes += len(component)
    return changes

