def solve(n, m, k, grid):
    def count_changes(grid):
        changes = [[0] * m for _ in range(n)]
        for i in range(n):
            for j in range(m):
                if i > 0 and grid[i][j] != grid[i-1][j]:
                    changes[i][j] += 1
                if j > 0 and grid[i][j] != grid[i][j-1]:
                    changes[i][j] += 1
        return sum(sum(row) for row in changes)

    def is_rectangular(grid):
        visited = [[False] * m for _ in range(n)]
        for i in range(n):
            for j in range(m):
                if not visited[i][j]:
                    x, y = i, j
                    value = grid[x][y]
                    rectangle = [(x, y)]
                    stack = [(x, y)]
                    visited[x][y] = True
                    while stack:
                        x, y = stack.pop()
                        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                            nx, ny = x + dx, y + dy
                            if (0 <= nx < n) and (0 <= ny < m) and grid[nx][ny] == value and not visited[nx][ny]:
                                stack.append((nx, ny))
                                rectangle.append((nx, ny))
                                visited[nx][ny] = True
                    x1, y1 = min(x for x, y in rectangle), min(y for x, y in rectangle)
                    x2, y2 = max(x for x, y in rectangle), max(y for x, y in rectangle)
                    if len(rectangle) != (x2 - x1 + 1) * (y2 - y1 + 1):
                        return False
        return True

    def brute_force(n, m, k, grid, index=0):
        if index == n * m:
            return float('inf') if not is_rectangular(grid) else count_changes(grid)
        i, j = divmod(index, m)
        best = float('inf')
        for value in [grid[i][j], 1 - grid[i][j]]:
            new_grid = [row[:] for row in grid]
            new_grid[i][j] = value
            result = brute_force(n, m, k, new_grid, index + 1)
            if result != float('inf'):
                best = min(best, result)
        return best

    result = brute_force(n, m, k, grid)
    return -1 if result > k else result


def main():
    n, m, k = map(int, input().split())
    grid = [list(map(int, input().split())) for _ in range(n)]
    print(solve(n, m, k, grid))


if __name__ == "__main__":
    main()
