    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < m

    visited = [[False]*m for _ in range(n)]
    def dfs(x, y, val):
        if not is_valid(x, y) or grid[x][y] != val or visited[x][y]:
            return 0
        visited[x][y] = True
        count = 1
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            count += dfs(nx, ny, val)
        return count

    def check_rectangle(x, y, val):
        min_x, max_x, min_y, max_y = n, -1, m, -1
        queue = [(x, y)]
        visited = [[False]*m for _ in range(n)]
        while queue:
            cx, cy = queue.pop(0)
            if not is_valid(cx, cy) or grid[cx][cy] != val or visited[cx][cy]:
                continue
            visited[cx][cy] = True
            min_x, max_x = min(min_x, cx), max(max_x, cx)
            min_y, max_y = min(min_y, cy), max(max_y, cy)
            for dx, dy in directions:
                nx, ny = cx + dx, cy + dy
                queue.append((nx, ny))
        size = (max_x - min_x + 1) * (max_y - min_y + 1)
        return sum(grid[i][j] == val for i in range(min_x, max_x+1) for j in range(min_y, max_y+1)) == size

    total_changes = 0
    for i in range(n):
        for j in range(m):
            if not visited[i][j]:
                count = dfs(i, j, grid[i][j])
                if not check_rectangle(i, j, grid[i][j]):
                    total_changes += count
    return -1 if total_changes > k else max(0, total_changes - k)

