        self.data = [[0] * n for _ in range(n)]

    def multiply(self, other: 'Matrix') -> 'Matrix':
        result = Matrix(self.n)
        for i in range(self.n):
            for j in range(self.n):
                for k in range(self.n):
                    result.data[i][j] += self.data[i][k] * other.data[k][j]
                    result.data[i][j] %= MOD
        return result

    def power(self, n: int) -> 'Matrix':
        if n == 1:
            return self
        half_pow = self.power(n // 2)
        if n % 2 == 0:
            return half_pow.multiply(half_pow)
        else:
            return half_pow.multiply(half_pow).multiply(self)

