        self.data = [[0] * n for _ in range(n)]

    def set(self, i, j, val):
        self.data[i][j] = val

    def get(self, i, j):
        return self.data[i][j]

    def mul(self, other):
        result = Matrix(self.n)
        for i in range(self.n):
            for j in range(self.n):
                for k in range(self.n):
                    result.set(i, j, add(result.get(i, j), mul(self.get(i, k), other.get(k, j))))
        return result

