            id_matrix = Matrix(self.n)
            for i in range(self.n):
                id_matrix.set(i, i, 1)
            return id_matrix
        elif n % 2 == 1:
            return self.mul(self.pow_mod(n-1))
        else:
            half_pow = self.pow_mod(n//2)
            return half_pow.mul(half_pow)

