        graph = []
        for i in range(n):
            neighbors = [j+1 for j in range(n) if i != j and (s[i] == s[j] or abs(ord(s[i]) - ord(s[j])) == 1)]
            graph.append(neighbors)
        graph_edges = set()
        for i, neighbors in enumerate(graph):
            for neighbor in neighbors:
                edge = tuple(sorted((i+1, neighbor)))
                graph_edges.add(edge)
        return graph_edges == set(edges)

    for s in product('abc', repeat=n):
        s = ''.join(s)
        if is_valid_string(s) and is_graph_equal(s, edges):
            return 'Yes\n' + s
    return 'No'

