    result = [None] * N
    current_time = 0
    end_times = []

    for i in range(N):
        start_time = max(0, min(current_time, T - breaks[i]))
        if len(end_times) < 2 or end_times[0] <= start_time:
            if len(end_times) == 2 and end_times[1] <= start_time:
                result[end_times.index(min(end_times))] = current_time - min(end_times)
                end_times.remove(min(end_times))
            elif len(end_times) < 2 or end_times[0] > end_times[1]:
                if end_times and end_times[0] < T:
                    end_times.append(end_times.pop(0))
            result[i] = start_time
            end_times.append(start_time + breaks[i])
