def min_effort_to_disrupt(n, k, sequence, efforts):
    def is_balanced(sequence):
        balance = 0
        for char in sequence:
            if char == '(':
                balance += 1
            else:
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    def get_minimum_effort_to_disrupt(efforts, k):
        efforts.sort()
        total_effort = 0
        for i in range(k + 1):
            total_effort += efforts[i]
        min_total_effort = total_effort
        for i in range(k + 1, len(efforts)):
            total_effort -= efforts[i - k - 1]
            total_effort += efforts[i]
            min_total_effort = min(min_total_effort, total_effort)
        return min_total_effort

    opening_brackets = [i for i, char in enumerate(sequence) if char == '(']
    closing_brackets = [i for i, char in enumerate(sequence) if char == ')']
    efforts_for_opening_to_closing = []
    efforts_for_closing_to_opening = []

    for index in opening_brackets:
        effort = efforts[index]
        efforts_for_opening_to_closing.append(effort)

    for index in closing_brackets:
        effort = efforts[index]
        efforts_for_closing_to_opening.append(-effort)

    if len(opening_brackets) - k > len(closing_brackets):
        return get_minimum_effort_to_disrupt(efforts_for_opening_to_closing, k)
    elif len(closing_brackets) - k > len(opening_brackets):
        return get_minimum_effort_to_disrupt(efforts_for_closing_to_opening, k)
    else:
        return '?'

