    possible_paths = set([tuple(range(N))])

    for item in items:
        new_possible_paths = set()
        if item not in item_stores:
            print("impossible")
            return

        for path in possible_paths:
            for i in item_stores[item]:
                if i > max_store and (i == path[0] or i == path[-1]):
                    new_path = list(path)
                    if i != path[0]:
                        new_path.reverse()
                    j = 0
                    while j < len(new_path) and new_path[j] < i:
