from collections import deque

def min_moves_to_goal(maze):
    rows, cols = len(maze), len(maze[0])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    goal_position = None

    for i in range(rows):
        for j in range(cols):
            if maze[i][j] == 'M':
                goal_position = (i, j)

    def bfs(start_position):
        queue = deque([(start_position, 0)])
        visited = {start_position}

        while queue:
            position, moves = queue.popleft()
            x, y = position

            if position == goal_position:
                return moves

            for dx, dy in directions:
                new_x, new_y = x + dx, y + dy
                new_position = (new_x, new_y)

                if 0 <= new_x < rows and 0 <= new_y < cols:
                    if maze[new_x][new_y] != '#':
                        if new_position not in visited:
                            queue.append((new_position, moves + 1))
                            visited.add(new_position)
                        if maze[new_x][new_y] == '_':
                            nx, ny = new_x + dx, new_y + dy
                            while 0 <= nx < rows and 0 <= ny < cols and maze[nx][ny] == '_':
                                nx += dx
                                ny += dy
                            if (nx, ny) not in visited:
                                queue.append(((nx, ny), moves + 1)
                                             if nx < rows and ny < cols else ((new_x, new_y), moves + 1))
                                visited.add((nx, ny))

        return -1

    result = [[0]*cols for _ in range(rows)]

    for i in range(rows):
        for j in range(cols):
            if maze[i][j] != '#':
                result[i][j] = bfs((i, j))

    return result


