    while queue:
        r, c = queue.popleft()
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if maze[nr][nc] == '#':
                    continue

                new_r, new_c = nr, nc
                while maze[new_r][new_c] == '_':
                    new_dr, new_dc = dr, dc
                    new_nr, new_nc = new_r + new_dr, new_c + new_dc
                    if 0 <= new_nr < rows and 0 <= new_nc < cols:
                        if maze[new_nr][new_nc] in ['.', 'M']:
                            new_r, new_c = new_nr, new_nc
                            break
                        elif maze[new_nr][new_nc] == '_':
                            new_r, new_c = new_nr, new_nc
