                distance = min_moves[r][c] + 1
                if distance < min_moves[new_r][new_c]:
                    min_moves[new_r][new_c] = distance
                    queue.append((new_r, new_c))

    return [[-1 if x == float('inf') else x for x in row] for row in min_moves]

