def compute_transition_matrix(graph):
    N = len(graph)
    transition_matrix = [[0.0] * N for _ in range(N)]

    for i in range(N):
        neighbors = graph[i]
        if not neighbors:
            transition_matrix[i][i] = 1.0
        else:
            prob = 1.0 / len(neighbors)
            for neighbor in neighbors:
                transition_matrix[neighbor][i] = prob

    return transition_matrix

def matrix_multiply(A, B):
    N = len(A)
    C = [[0.0] * N for _ in range(N)]

    for i in range(N):
        for j in range(N):
            for k in range(N):
                C[i][j] += A[i][k] * B[k][j]

    return C

def compute_probability(walk, transition_matrix):
    L = len(walk)
    N = len(transition_matrix)

    # Compute the probability of success at each step
    probabilities = [0.0] * L
    probabilities[0] = 1.0 / N

    for i in range(L - 1):
        current_room = walk[i]
        next_room = walk[i + 1]

        # Update the probability distribution using the transition matrix
        new_probabilities = [0.0] * N
        for j in range(N):
            for k in range(N):
                if k == current_room:
                    continue
                if k == next_room or (j != current_room and j != next_room):
                    new_probabilities[j] += probabilities[k] * transition_matrix[k][j]

        probabilities = new_probabilities

    # Compute the final probability of success
    final_probability = 0.0
    for i in range(N):
        if i == walk[-1]:
            continue
