        z = (planetoid[3] + planetoid[6]*t) % nz
        return x, y, z

    def get_collision_time(planetoid1, planetoid2):
        for t in range(nx*ny*nz):
            x1, y1, z1 = get_location(planetoid1, t)
            x2, y2, z2 = get_location(planetoid2, t)
            if (x1, y1, z1) == (x2, y2, z2):
                return t
        return float('inf')

    def merge_planetoids(planetoid1, planetoid2):
        m = planetoid1[0] + planetoid2[0]
        vx = round((planetoid1[0]*planetoid1[4] + planetoid2[0]*planetoid2[4]) / m)
        vy = round((planetoid1[0]*planetoid1[5] + planetoid2[0]*planetoid2[5]) / m)
        vz = round((planetoid1[0]*planetoid1[6] + planetoid2[0]*planetoid2[6]) / m)
        return [m, 0, 0, 0, vx, vy, vz]

    def update_planetoids(planetoids, t):
        new_planetoids = []
        for i in range(len(planetoids)):
            merged = False
            for j in range(i+1, len(planetoids)):
                if get_location(planetoids[i], t) == get_location(planetoids[j], t):
                    new_planetoid = merge_planetoids(planetoids[i], planetoids[j])
                    new_planetoids.append(new_planetoid)
                    merged = True
                    break
            if not merged:
                new_planetoids.append(planetoids[i])
        return new_planetoids

    last_collision_time = -1
    while True:
        collision_times = []
        for i in range(len(planetoids)):
            for j in range(i+1, len(planetoids)):
                t = get_collision_time(planetoids[i], planetoids[j])
                if t != float('inf'):
                    collision_times.append(t)
        if not collision_times:
            break
        t = min(collision_times)
        last_collision_time = t
        planetoids = update_planetoids(planetoids, t)

