import sys

def calculate_collision_time(p1, p2):
    x_diff = p1['x'] - p2['x']
    y_diff = p1['y'] - p2['y']
    z_diff = p1['z'] - p2['z']

    vx_diff = p1['vx'] - p2['vx']
    vy_diff = p1['vy'] - p2['vy']
    vz_diff = p1['vz'] - p2['vz']

    if vx_diff == 0 and x_diff != 0:
        return float('inf')
    if vy_diff == 0 and y_diff != 0:
        return float('inf')
    if vz_diff == 0 and z_diff != 0:
        return float('inf')

    t_x = None
    if vx_diff != 0:
        t_x = x_diff / vx_diff

    t_y = None
    if vy_diff != 0:
        t_y = y_diff / vy_diff

    t_z = None
    if vz_diff != 0:
        t_z = z_diff / vz_diff

    possible_ts = [t for t in (t_x, t_y, t_z) if t is not None]
    if len(possible_ts) == 0:
        return float('inf')
    else:
        t = min([abs(t) for t in possible_ts])
        return round(t)

def main():
    n, nx, ny, nz = map(int, input().split())
    planetoids = []
    for _ in range(n):
        m, x, y, z, vx, vy, vz = map(int, input().split())
        planetoids.append({
            'm': m,
            'x': x,
            'y': y,
            'z': z,
            'vx': vx,
            'vy': vy,
            'vz': vz
        })

    collisions = []
    for i in range(len(planetoids)):
        for j in range(i + 1, len(planetoids)):
            t = calculate_collision_time(planetoids[i], planetoids[j])
            if t != float('inf'):
                collisions.append((i, j, round(t)))

    collisions.sort(key=lambda x: x[2])

    while collisions:
        i, j, t = collisions.pop(0)

        # move planetoids to the time of collision
        for k in range(len(planetoids)):
            p = planetoids[k]
            p['x'] = (p['x'] + p['vx'] * t) % nx
            p['y'] = (p['y'] + p['vy'] * t) % ny
            p['z'] = (p['z'] + p['vz'] * t) % nz

        # merge planetoids
        p1, p2 = planetoids[i], planetoids[j]
        new_m = p1['m'] + p2['m']
        new_vx = round((p1['vx'] * p1['m'] + p2['vx'] * p2['m']) / (p1['m'] + p2['m']))
        new_vy = round((p1['vy'] * p1['m'] + p2['vy'] * p2['m']) / (p1['m'] + p2['m']))
        new_vz = round((p1['vz'] * p1['m'] + p2['vz'] * p2['m']) / (p1['m'] + p2['m']))

        planetoids[i] = {
            'm': new_m,
            'x': p1['x'],
            'y': p1['y'],
            'z': p1['z'],
            'vx': new_vx,
            'vy': new_vy,
            'vz': new_vz
        }
        planetoids.pop(j)

        # remove collisions that involve the merged planetoid
        collisions = [(i, j, t) for i, j, t in collisions if i != j and i < len(planetoids) and j < len(planetoids)]

        # calculate new collision times for the merged planetoid
        new_collisions = []
        for k in range(len(planetoids)):
            if k == i:
                continue
            t = calculate_collision_time(planetoids[i], planetoids[k])
            if t != float('inf'):
                new_collisions.append((i, k, round(t)))
        collisions.extend(new_collisions)
        collisions.sort(key=lambda x: x[2])

    # sort the final planetoids by mass and location
    planetoids.sort(key=lambda p: (-p['m'], p['x'], p['y'], p['z']))

    print(len(planetoids))
