    s = list(iterable)
    return chain.from_iterable(combinations(s, r) for r in range(len(s)+1))

def calculate_distance(x1, y1, x2, y2):
    return math.sqrt((x2 - x1)**2 + (y2 - y1)**2)

def is_valid_line(lamps, line_lamps):
    total_energy = sum([lamp[2] for lamp in lamps])
    inside_energy = sum([lamp[2] for lamp in line_lamps])
    outside_energy = total_energy - inside_energy
    return math.isclose(inside_energy, outside_energy)

def calculate_line_length(lamps, line_lamps):
    if not is_valid_line(lamps, line_lamps):
        return float('inf')

    points = [(lamp[0], lamp[1]) for lamp in line_lamps]
