import sys
from collections import defaultdict, deque

def read_input():
    n, m, s, t = map(int, input().split())
    graph = defaultdict(list)
    for _ in range(m):
        u, v, c, w = map(int, input().split())
        graph[u].append((v, c, w))
        graph[v].append((u, 0, -w))  # Residual edge
    return n, m, s, t, graph

def bellman_ford(graph, s):
    distance = {node: float('inf') for node in range(len(graph))}
    distance[s] = 0
    for _ in range(len(graph) - 1):
        for u in graph:
            for v, c, w in graph[u]:
                if c > 0 and distance[u] + w < distance[v]:
                    distance[v] = distance[u] + w
    return distance

def edmonds_karp(graph, s, t, flow_limit=float('inf')):
    parent = {}
    max_flow = 0
    while True:
        queue = deque([s])
        visited = {s}
        while queue and t not in parent:
            u = queue.popleft()
            for v, c, _ in graph[u]:
                if v not in visited and c > 0:
                    visited.add(v)
                    parent[v] = (u, c)
                    queue.append(v)
        if t not in parent:
            break
        path_flow = float('inf')
        u = t
        while u != s:
            _, c, _ = parent[u]
            path_flow = min(path_flow, c)
            u = parent[u][0]
        max_flow += path_flow
        if max_flow >= flow_limit:
            break
        u = t
        while u != s:
            p, c, w = parent[u]
            graph[p].remove((u, c, w))
            graph[u].append((p, 0, -w))  # Add residual edge
            u = p
    return max_flow

def min_cost_max_flow(graph, s, t):
    n = len(graph)
    flow_limit = sum(c for edges in graph.values() for _, c, _ in edges) + 1
    potential = bellman_ford(graph, s)
    residual_graph = defaultdict(list)
    for u in range(n):
        for v, c, w in graph[u]:
            reduced_cost = w + potential[u] - potential[v]
            if reduced_cost < 0:
                residual_graph[u].append((v, c, reduced_cost))
    max_flow = edmonds_karp(residual_graph, s, t, flow_limit)
    min_cost = sum(potential[t] * max_flow for _ in range(n))
    return max_flow, min_cost

def main():
    n, m, s, t, graph = read_input()
    max_flow, min_cost = min_cost_max_flow(graph, s, t)
    print(max_flow, min_cost)

