import sys
from collections import defaultdict, deque

class Edge:
    def __init__(self, to, capacity, weight):
        self.to = to
        self.capacity = capacity
        self.weight = weight
        self.flow = 0

def add_edge(graph, from_node, to_node, capacity, weight):
    graph[from_node].append(Edge(to_node, capacity, weight))
    graph[to_node].append(Edge(from_node, 0, -weight))

def bellman_ford(graph, source):
    distance = [float('inf')] * len(graph)
    distance[source] = 0
    for _ in range(len(graph) - 1):
        for from_node in range(len(graph)):
            for edge in graph[from_node]:
                if edge.capacity > edge.flow and distance[from_node] + edge.weight < distance[edge.to]:
                    distance[edge.to] = distance[from_node] + edge.weight
    return distance

def dijkstra(graph, source, sink, potential):
    distance = [float('inf')] * len(graph)
    distance[source] = 0
    parent = [-1] * len(graph)
    queue = [(0, source)]
    while queue:
        current_distance, current_node = min(queue)
        queue.remove((current_distance, current_node))
        if current_distance > distance[current_node]:
            continue
        for edge in graph[current_node]:
            residual_capacity = edge.capacity - edge.flow
            reduced_weight = edge.weight + potential[current_node] - potential[edge.to]
            if residual_capacity > 0 and current_distance + reduced_weight < distance[edge.to]:
                distance[edge.to] = current_distance + reduced_weight
                parent[edge.to] = current_node
                queue.append((distance[edge.to], edge.to))
    return distance, parent

def min_cost_max_flow(graph, source, sink):
    flow = 0
    cost = 0
    potential = bellman_ford(graph, source)
    while True:
        distance, parent = dijkstra(graph, source, sink, potential)
        if distance[sink] == float('inf'):
            break
        path_flow = float('inf')
        current_node = sink
        while current_node != source:
            for edge in graph[parent[current_node]]:
                if edge.to == current_node:
                    path_flow = min(path_flow, edge.capacity - edge.flow)
            current_node = parent[current_node]
        flow += path_flow
        cost += distance[sink] * path_flow
        current_node = sink
        while current_node != source:
            for i, edge in enumerate(graph[parent[current_node]]):
                if edge.to == current_node:
                    graph[parent[current_node]][i].flow += path_flow
            for i, edge in enumerate(graph[current_node]):
                if edge.to == parent[current_node]:
                    graph[current_node][i].flow -= path_flow
            potential[current_node] = distance[current_node]
            current_node = parent[current_node]
    return flow, cost

def main():
    n, m, s, t = map(int, input().split())
    graph = [[] for _ in range(n)]
    for _ in range(m):
        u, v, c, w = map(int, input().split())
        add_edge(graph, u, v, c, w)
    flow, cost = min_cost_max_flow(graph, s, t)
    print(flow, cost)

if __name__ == '__main__':
