def calculate_distance(a, b):
    """Calculates the distance between two nodes"""
    if a == b:
        return 0
    elif a % b == 0 and b != 1:
        return 1 + calculate_distance(a // b, b)
    else:
        return 1 + calculate_distance(b, a)

def get_lowest_prime_divisor(n):
