        if n % i == 0:
            return i
    return n

def get_path_length(node):
    """Get the path length from node to its root (node 1)"""
    length = 0
    while node > 1:
        lowest_prime_factor = get_lowest_prime_factor(node)
        node //= lowest_prime_factor
        length += 1
    return length

