from collections import defaultdict, deque

def get_prime_factors(n):
    factors = []
    while n % 2 == 0:
        factors.append(2)
        n //= 2
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        while n % i == 0:
            factors.append(i)
            n //= i
    if n > 2:
        factors.append(n)
    return factors

def get_lowest_prime_factor(n):
    factors = get_prime_factors(n)
    if not factors:
        return None
    return min(factors)

def bfs(graph, start):
    queue = deque([(start, 0)])
    visited = set([start])
    distances = defaultdict(int)
    while queue:
        node, distance = queue.popleft()
        distances[node] = distance
        for neighbor in graph[node]:
            if neighbor not in visited:
                queue.append((neighbor, distance + 1))
                visited.add(neighbor)
    return distances

def get_shortest_distances(graph, nodes):
    shortest_distances = []
    for node in nodes:
        distances = bfs(graph, node)
        shortest_distances.append(distances)
    return shortest_distances

def calculate_total_distance(nodes, shortest_distances):
    total_distance = 0
    for i, node in enumerate(nodes):
        for j, other_node in enumerate(nodes):
            if i != j:
                total_distance += shortest_distances[i][other_node]
    return total_distance

def get_factorial(n):
    factorial = 1
    for i in range(2, n + 1):
        factorial *= i
    return factorial

