            for v, w in edges[u]:
                heappush(pq, (d + w, v))
        return mindist

    costs = [[0.0 for _ in range(t)] for _ in range(s)]
    for i, spring in enumerate(springs):
        dists = dijkstra(spring)
        for j, town in enumerate(towns):
            costs[i][j] = max(0.0, float(dists[town]))

    def hungarian(n, cost):
        INF = 10**9
        u = [0] * n
        v = [INF] * n
        p = [None] * n
        way = [None] * n

        for i in range(n):
            minv = INF
            for j in range(n):
                if cost[i][j] - u[i] - v[j] < minv:
                    minv = cost[i][j] - u[i] - v[j]
            u[i] += minv

        for i in range(n):
            p[i] = None
            way[i] = i

        while True:
            minv = INF
            used = [False] * n
            for i in range(n):
                if not p[i]:
                    for j in range(n):
                        if cost[i][j] - u[i] - v[j] < minv and not used[j]:
                            minv = cost[i][j] - u[i] - v[j]
                            way[i] = j
            for i in range(n):
                if p[i]: continue
                for j in range(n):
                    if cost[i][way[i]] - u[i] - v[way[i]] == 0 and not used[j]:
                        used[j] = True
                        p[i] = way[i]
            if all(used): break

        while True:
            changed = False
            for i in range(n):
                for j in range(n):
                    if cost[i][j] - u[i] - v[j] == 0 and not used[j]:
                        changed = True
                        p[i] = j
                        way[i] = j
                        break
                if changed: break
            if not changed: break

        for i in range(n):
            u[i] += minv
            v[p[i]] -= minv

        return sum([cost[i][p[i]] for i in range(n)])

    if s != t:
        print('IMPOSSIBLE')
    else:
        print(hungarian(s, costs))

if __name__ == "__main__":
    main()
