import sys
from math import sqrt, inf
from heapq import heappop, heappush

def distance(x1, y1, x2, y2):
    return sqrt((x1 - x2) ** 2 + (y1 - y2) ** 2)

def dijkstra(graph, start):
    distances = {node: inf for node in graph}
    distances[start] = 0
    queue = [(0, start)]

    while queue:
        current_distance, current_node = heappop(queue)

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node].items():
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heappush(queue, (distance, neighbor))

    return distances

def main():
    n, s, t, q = map(int, input().split())
    hills = []

    for _ in range(n):
        x, y, h = map(int, input().split())
        hills.append((x, y, h))

    springs = list(map(lambda x: int(x) - 1, input().split()))
    towns = list(map(lambda x: int(x) - 1, input().split()))

    graph = {}

    for i in range(n):
        graph[i] = {}

        for j in range(n):
            if i != j:
                dist = distance(hills[i][0], hills[i][1], hills[j][0], hills[j][1])

                if hills[j][2] < hills[i][2] and dist <= q:
                    graph[i][j] = dist

    spring_dists = {}

    for spring in springs:
        distances = dijkstra(graph, spring)

        for town in towns:
            if town not in spring_dists or distances[town] < spring_dists[town]:
                spring_dists[(spring, town)] = distances[town]

    min_length = inf
    used_springs = set()

    def backtrack(towns_left):
        nonlocal min_length

        if len(used_springs) == t:
            return 0

        for spring in springs:
            if spring not in used_springs:
                for town in towns_left[:]:
                    if (spring, town) in spring_dists:
                        dist = spring_dists[(spring, town)]
                        new_towns_left = [t for t in towns_left if t != town]

                        length = backtrack(new_towns_left)

                        if length != inf:
                            min_length = min(min_length, dist + length)

                        used_springs.add(spring)
                        break
                used_springs.remove(spring)

        return min_length

    result = backtrack(towns)

    if result == inf:
        print("IMPOSSIBLE")
    else:
        print("{:.6f}".format(result))

if __name__ == "__main__":
