        hills.append((x, y, h))
    springs = list(map(lambda x: int(x) - 1, input().split()))
    towns = list(map(lambda x: int(x) - 1, input().split()))

    # Create a distance matrix
    distance_matrix = np.zeros((n, n))
    for i in range(n):
        for j in range(i+1, n):
            dist = calculate_distance(hills[i], hills[j])
            if dist <= q and hills[i][2] > hills[j][2]:
                distance_matrix[i, j] = dist
            elif dist <= q and hills[i][2] < hills[j][2]:
                distance_matrix[j, i] = dist

    # Create a matrix of distances from springs to towns
    spring_town_distances = np.zeros((s, t))
    for i, spring in enumerate(springs):
        for j, town in enumerate(towns):
            if distance_matrix[spring, town] > 0:
                spring_town_distances[i, j] = distance_matrix[spring, town]
            else:
                # Find the shortest path from spring to town
                visited = set()
                stack = [(spring, 0)]
                while stack:
                    current_node, current_distance = stack.pop(0)
                    if current_node == town:
                        spring_town_distances[i, j] = current_distance
                        break
                    for next_node in range(n):
                        if distance_matrix[current_node, next_node] > 0 and next_node not in visited:
                            stack.append((next_node, current_distance + distance_matrix[current_node, next_node]))
                            visited.add(next_node)
                if spring_town_distances[i, j] == 0:
                    spring_town_distances[i, j] = np.inf

    # Find the minimum total length of all aqueducts needed to supply each town with fresh water from its own unique spring
    min_total_length = np.inf
    for permutation in permutations(springs, t):
        total_length = 0
        for i, town in enumerate(towns):
            distance_to_spring = np.inf
            for j, spring in enumerate(permutation):
                if spring_town_distances[springs.index(spring), towns.index(town)] < distance_to_spring:
                    distance_to_spring = spring_town_distances[springs.index(spring), towns.index(town)]
            total_length += distance_to_spring
        min_total_length = min(min_total_length, total_length)

    if min_total_length == np.inf:
        print("IMPOSSIBLE")
    else:
        print(f"{min_total_length:.6f}")

