import sys

def find_components(rows, cols):
    components = []
    visited = set()

    def bfs(r, c, component):
        queue = deque([(r, c)])
        while queue:
            r, c = queue.popleft()
            if (r, c) not in visited:
                visited.add((r, c))
                component.append((r, c))

                for nr, nc in [(r - 1, c), (r + 1, c)]:
                    if 1 <= nr <= n and (nr, c) in rows[r] and (nr, c) not in visited:
                        queue.append((nr, c))

                for nr, nc in [(r, c - 1), (r, c + 1)]:
                    if 1 <= nc <= m and (r, nc) in cols[c] and (r, nc) not in visited:
                        queue.append((nr, nc))

    for r in range(1, n + 1):
        for c in range(1, m + 1):
            if (r, c) not in visited:
                component = []
                bfs(r, c, component)
                components.append(component)

    return components


