from sys import stdin, stdout
import math

def find(parent, i):
    if parent[i] == i:
        return i
    return find(parent, parent[i])

def union(parent, rank, x, y):
    xroot = find(parent, x)
    yroot = find(parent, y)

    if rank[xroot] < rank[yroot]:
        parent[xroot] = yroot
    elif rank[xroot] > rank[yroot]:
        parent[yroot] = xroot
    else:
        parent[yroot] = xroot
        rank[xroot] += 1

def main():
    n = int(input())
    h = []
    v = []
    for _ in range(n):
        h.append(list(map(int, stdin.readline().split())))
    for _ in range(n):
        v.append(list(map(int, stdin.readline().split())))

    parent = [i for i in range(n*n)]
    rank = [0]*(n*n)
    ans = 0

    def compress(t):
        groups = {}
        index_map = {}
        idx = 0
        for i in range(n):
            for j in range(n):
                if (h[i][j] + v[i][j]*t) not in groups:
                    groups[(h[i][j] + v[i][j]*t)] = []
                    index_map[(h[i][j] + v[i][j]*t)] = idx
                    idx += 1
                parent[i*n+j] = index_map[(h[i][j] + v[i][j]*t)]

        for i in range(n):
            for j in range(n):
                if (i < n-1 and h[i][j] + t*v[i][j] == h[i+1][j] + t*v[i+1][j]):
                    union(parent, rank, index_map[h[i][j]+t*v[i][j]], index_map[h[i+1][j]+t*v[i+1][j]])
                if (j < n-1 and h[i][j] + t*v[i][j] == h[i][j+1] + t*v[i][j+1]):
                    union(parent, rank, index_map[h[i][j]+t*v[i][j]], index_map[h[i][j+1]+t*v[i][j+1]])

        count = {}
        for i in range(n):
            for j in range(n):
                group_index = find(parent, index_map[(h[i][j] + v[i][j]*t)])
                if group_index not in count:
                    count[group_index] = 0
                count[group_index] += 1

        return max(count.values())

    left, right = -1000000, 1000000
    while (left <= right):
        mid = (left + right) // 2
        if compress(mid//10**6) > compress((mid+1)//10**6):
            ans = compress(mid//10**6)
            right = mid - 1
        else:
            left = mid + 1

    print(ans)

main()
