import sys
from collections import defaultdict

def solve():
    n, m = map(int, input().split())
    graph = [[] for _ in range(n)]
    for _ in range(m):
        u, v = map(lambda x: int(x) - 1, input().split())
        graph[u].append(v)
        graph[v].append(u)

    min_steps = float('inf')
    best_sequence = None

    def is_connected(graph):
        visited = set()
        stack = [0]
        while stack:
            node = stack.pop()
            if node not in visited:
                visited.add(node)
                for neighbor in graph[node]:
                    stack.append(neighbor)
        return len(visited) == n

    def bfs(start, graph):
        queue = [(start, 0)]
        visited = set([start])
        max_distance = 0
        while queue:
            node, distance = queue.pop(0)
            max_distance = max(max_distance, distance)
            for neighbor in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, distance + 1))
        return max_distance

    def is_full_connected(graph):
        for i in range(n):
            if bfs(i, graph) != 0:
                return False
        return True

    def introduce(node, graph):
        new_graph = [neighbors[:] for neighbors in graph]
        for u in graph[node]:
            for v in graph[node]:
                if u != v and v not in new_graph[u]:
                    new_graph[u].append(v)
                    new_graph[v].append(u)
        return new_graph

    def dfs(current_node, current_sequence, current_graph):
        nonlocal min_steps, best_sequence
        if is_full_connected(current_graph):
            if len(current_sequence) < min_steps:
                min_steps = len(current_sequence)
                best_sequence = current_sequence[:]
            return

        for node in range(n):
            new_graph = introduce(node, current_graph)
            if not is_connected(new_graph):
                continue
            dfs(current_node + 1, current_sequence + [node], new_graph)

    dfs(0, [], graph)
    print(min_steps)
    print(*[i + 1 for i in best_sequence])

