def min_steps_to_friendship(n, m, edges):
    # Create an adjacency matrix to represent the graph
    adj_matrix = [[0] * n for _ in range(n)]
    for u, v in edges:
        adj_matrix[u-1][v-1] = 1
        adj_matrix[v-1][u-1] = 1

    def is_connected(adj_matrix):
        # Check if the graph is connected using BFS
        visited = [0] * n
        queue = [0]
        visited[0] = 1
        while queue:
            node = queue.pop(0)
            for i in range(n):
                if adj_matrix[node][i] and not visited[i]:
                    queue.append(i)
                    visited[i] = 1
        return all(visited)

    def get_degree(adj_matrix):
        # Calculate the degree of each node
        degrees = [sum(row) for row in adj_matrix]
        return degrees

    steps = 0
    selected_guests = []
    while not is_connected(adj_matrix) or len([1 for i in range(n) for j in range(i+1, n) if adj_matrix[i][j] == 0]) > 0:
        max_degree_node = -1
        max_degree = -1
        degrees = get_degree(adj_matrix)
        for i in range(n):
            if degrees[i] > max_degree:
                max_degree = degrees[i]
                max_degree_node = i

        selected_guests.append(max_degree_node + 1)

        # Update the adjacency matrix after selecting a guest
        for i in range(n):
            if adj_matrix[max_degree_node][i]:
                for j in range(n):
                    if adj_matrix[max_degree_node][j]:
                        adj_matrix[i][j] = 1
                        adj_matrix[j][i] = 1

        steps += 1

    return steps, selected_guests


