def min_turns_to_show_difference(n, A, B, intersections):
    def traverse(start, path):
        seen = set()
        queue = [(start, path)]
        while queue:
            node, path = queue.pop(0)
            if node in seen:
                continue
            seen.add(node)
            yield node, path
            for turn, neighbor in ((0, intersections[node][0]), (1, intersections[node][1])):
                queue.append((neighbor, path + [turn]))

    def distinguish(A_path, B_path):
        for A_node, A_turns in traverse(A, []):
            for B_node, B_turns in traverse(B, []):
                if len(A_turns) != len(B_turns):
                    continue
                if intersections[A_node][2] != intersections[B_node][2]:
                    return max(len(A_turns), 1)
        return float('inf')

    turns = distinguish(A, B)
    return "indistinguishable" if turns == float('inf') else turns

