def calculate_probability(n, probabilities):
    max_prob = 0
    for i in range(1 << n):
        prob = 1
        ones_count = 0
        for j in range(n):
            if (i & (1 << j)) > 0:
                prob *= probabilities[j]
                ones_count += 1
            else:
