def calculate_probability(friends):
    max_prob = 0
    for r in range(1, len(friends) + 1):
        for combo in combinations(friends, r):
            prob = 1
            for p in combo:
                prob *= p
            for p in [x for x in friends if x not in combo]:
                prob *= (1 - p)
            max_prob = max(max_prob, prob)
    return max_prob

def calculate_total_probability(friends):
    total_prob = 0
    n = len(friends)
    for r in range(1, n + 1):
        for combo in combinations(friends, r):
            prob = 1
            for p in combo:
                prob *= p
            for p in [x for x in friends if x not in combo]:
                prob *= (1 - p)
            total_prob += prob
    return total_prob

