import math
from collections import defaultdict
from sys import stdin, stdout

MOD = 10**9 + 7

def is_prime(n):
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def prime_factors(n):
    factors = []
    divisor = 2
    while n > 1:
        if n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        else:
            divisor += 1
    return factors

def count_set_bits(n):
    count = 0
    while n > 0:
        count += n & 1
        n >>= 1
    return count

def sieve_of_eratosthenes(n):
    primes = [True] * (n + 1)
    primes[0] = primes[1] = False
    for i in range(2, int(math.sqrt(n)) + 1):
        if primes[i]:
            for j in range(i*i, n + 1, i):
                primes[j] = False
    return [i for i in range(2, n + 1) if primes[i]]

def factorial(n):
    result = 1
    for i in range(1, n + 1):
        result *= i
    return result

def nCr(n, r):
    return factorial(n) // (factorial(r) * factorial(n - r))

def main():
    n, m = map(int, input().split())
    gyms = []
    for _ in range(n):
        gym = list(map(int, input().split()))[1:]
        gyms.append(gym)

    freq = defaultdict(list)
    for i, gym in enumerate(gyms):
        for pokemon in gym:
            freq[pokemon].append(i)

    graph = [[] for _ in range(m + 1)]
    for pokemon in freq:
        if len(freq[pokemon]) > 1:
            for i in range(len(freq[pokemon])):
                for j in range(i + 1, len(freq[pokemon])):
                    graph[freq[pokemon][i]].append((freq[pokemon][j], pokemon))
                    graph[freq[pokemon][j]].append((freq[pokemon][i], pokemon))

    visited = [False] * m
    components = []
    for i in range(m):
        if not visited[i]:
            component = []
            stack = [i]
            while stack:
                node = stack.pop()
                if not visited[node]:
                    visited[node] = True
                    component.append(node)
                    for neighbor, _ in graph[node]:
                        if not visited[neighbor]:
                            stack.append(neighbor)
            components.append(component)

    result = 1
    for component in components:
        result *= math.factorial(len(component))
        result %= MOD

    print(result)

