from collections import deque

def min_moves_to_solve(puzzle):
    target = ['RGBY', 'RGBY', 'RGBY', 'RGBY']
    queue = deque([(puzzle, 0)])
    visited = set()
    while queue:
        puzzle_state, moves = queue.popleft()
        if puzzle_state == target:
            return moves
        for i in range(4):
            # move row left or right
            for direction in [-1, 1]:
                new_puzzle_state = [list(row) for row in puzzle_state]
                new_puzzle_state[i] = new_puzzle_state[i][-direction:] + new_puzzle_state[i][:-direction]
                new_puzzle_state = [''.join(row) for row in new_puzzle_state]
                if tuple(new_puzzle_state) not in visited:
                    queue.append((new_puzzle_state, moves + 1))
                    visited.add(tuple(new_puzzle_state))
        for j in range(4):
            # move column up or down
            for direction in [-1, 1]:
                new_puzzle_state = []
                for i in range(4):
                    row = list(puzzle_state[i])
                    new_row = [0]*4
                    for k in range(4):
                        new_row[(k - j*direction) % 4] = row[k]
                    new_puzzle_state.append(''.join(new_row))
                if tuple(new_puzzle_state) not in visited:
                    queue.append((new_puzzle_state, moves + 1))
                    visited.add(tuple(new_puzzle_state))

