import sys

def transportation_switching_scheme(t, n, transportations, points):
    min_distance = [transportation[0] for transportation in transportations]
    max_heading_range = [transportation[1] for transportation in transportations]

    def check_transportation(transportation_index, start_point, end_point):
        total_distance = 0
        heading_angle = 0
        for i in range(start_point, end_point):
            total_distance += points[i][0]
            heading_angle += points[i][1]
            if abs(heading_angle) > max_heading_range[transportation_index]:
                return False
        if total_distance < min_distance[transportation_index]:
            return False
        return True

    def dp(current_point, last_transportation):
        if current_point == n - 1:
            return 0
        min_calls = float('inf')
        for transportation in range(t):
            for end_point in range(current_point + 1, n):
                if check_transportation(transportation, current_point, end_point):
                    calls = dp(end_point, transportation) + (last_transportation != transportation)
                    min_calls = min(min_calls, calls)
        return min_calls

    result = float('inf')
    for transportation in range(t):
        for end_point in range(1, n):
            if check_transportation(transportation, 0, end_point):
                calls = dp(end_point, transportation) + 1
                result = min(result, calls)

    return -1 if result == float('inf') else result

def main():
    input_lines = sys.stdin.readlines()
    t, n = map(int, input_lines[0].split())
    transportations = [list(map(int, line.split())) for line in input_lines[1:t+1]]
    points = [list(map(int, line.split())) for line in input_lines[t+1:]]
    result = transportation_switching_scheme(t, n, transportations, points)
    if result == -1:
        print('IMPOSSIBLE')
    else:
        print(result)

if __name__ == "__main__":
    main()
