    for p in range(1, min(k, n) + 1):
        q = (k - p + 1)
        if q <= m - 1:
            area = max((n // p), (m // q))
            if p * (n // p) != n or q * (m // q) != m:
                return min(n, m)
            else:
                return area
    return -1

n, m, k = map(int, input().split())
print(max_min_area(n, m, k))
