import sys

def solve(n, m, k):
    if k > n + m - 2:
        return -1
    if k == 0:
        return n * m
    pieces = [(n * m)]
    for _ in range(k):
        max_piece_index = pieces.index(max(pieces))
        piece = pieces.pop(max_piece_index)
        if piece % 2 != 0 and (piece + 1) // 2 not in pieces:
            pieces.append((piece + 1) // 2)
        pieces.append(piece // 2)
    return min(pieces)

n, m, k = map(int, sys.stdin.readline().split())
print(solve(n, m, k))
