def max_smallest_area(n, m, k):
    if k > n + m - 2:
        return -1

    def check(x):
        return (n // x) * (m // x) >= ((k + 1) // 2) and (n % x) * (m % x) >= (k % 2)

    l, r = 1, min(n, m)
    while l < r:
        mid = (l + r) // 2
        if check(mid):
            l = mid + 1
        else:
            r = mid

    return n * m // ((n - 1) // (l - 1) + 1) // ((m - 1) // (l - 1) + 1)

n, m, k = map(int, input().split())
print(max_smallest_area(n, m, k))
