import sys

def max_smallest_piece(n, m, k):
    if n * m - 1 < k or (k > 0 and min(n, m) == 1):
        return -1

    x = [n] + [1] * (k // 2)
    y = [m] + [1] * ((k + 1) // 2)

    for i in range(1, len(x)):
        if x[i] < x[0]:
            break
        x[0], x[i] = x[i], x[0]

    for i in range(1, len(y)):
        if y[i] < y[0]:
            break
        y[0], y[i] = y[i], y[0]

    return min(x[0], y[0])

